import numpy as np
# MECHANISM: Penalize bins with small remaining capacity more heavily, encouraging spreading items over multiple bins

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    return 1 / bins.clip(min=item)

import numpy as np
# MECHANISM: Prioritize based on the logarithm of the remaining capacity to encourage spreading items over multiple bins.

def priority(item, bins):
    return np.log(bins / item)

import numpy as np
# MECHANISM: Penalty for bins with leftover space smaller than the smallest item (20)
def priority(item: float, bins: np.ndarray) -> np.ndarray:
    min_item_size = 20
    penalty = np.where(bins < min_item_size, bins / min_item_size, 0)
    return -(bins - item - penalty)

import numpy as np

# MECHANISM: Penalize bins with small remaining capacity more heavily, but also consider the item size to avoid spreading too much

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    return (1 / bins.clip(min=item)) * (bins / item)

import numpy as np
# MECHANISM: Prioritize based on the square root of the remaining capacity to encourage spreading items over multiple bins.

def priority(item, bins):
    return np.sqrt(bins / item)
